import re
from typing import List, Tuple

# Token types
NUMBER, PLUS, MINUS, TIMES, DIVIDE, LPAREN, RPAREN, EOF = (
    'NUMBER', 'PLUS', 'MINUS', 'TIMES', 'DIVIDE', 'LPAREN', 'RPAREN', 'EOF'
)

# Token dataclass
class Token:
    def __init__(self, type_: str, value: str = None):
        self.type = type_
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

# Lexer: converts the input string into a list of tokens
def tokenize(expr: str) -> List[Token]:
    token_spec = [
        (NUMBER,   r'\d+(\.\d*)?|\.\d+'),  # Integer or decimal number
        (PLUS,     r'\+'),
        (MINUS,    r'-'),
        (TIMES,    r'\*'),
        (DIVIDE,   r'/'),
        (LPAREN,   r'\('),
        (RPAREN,   r'\)'),
        ('SKIP',   r'[ \t]+'),            # Skip spaces and tabs
    ]
    tok_regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in token_spec)
    get_token = re.compile(tok_regex).match
    pos = 0
    tokens = []
    while pos < len(expr):
        m = get_token(expr, pos)
        if not m:
            raise SyntaxError(f'Unexpected character: {expr[pos]!r} at position {pos}')
        typ = m.lastgroup
        if typ == 'SKIP':
            pass
        else:
            val = m.group(typ)
            tokens.append(Token(typ, val))
        pos = m.end()
    tokens.append(Token(EOF))
    return tokens

# Parser / Evaluator using recursive descent
class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0
        self.current_token = self.tokens[self.pos]

    def error(self, msg: str):
        raise SyntaxError(msg)

    def eat(self, token_type: str):
        if self.current_token.type == token_type:
            self.pos += 1
            self.current_token = self.tokens[self.pos]
        else:
            self.error(f'Expected token {token_type} but got {self.current_token.type}')

    # Grammar:
    # expr   : term ((PLUS | MINUS) term)*
    # term   : factor ((TIMES | DIVIDE) factor)*
    # factor : (PLUS | MINUS) factor | NUMBER | LPAREN expr RPAREN

    def parse(self) -> float:
        return self.expr()

    def expr(self) -> float:
        result = self.term()
        while self.current_token.type in (PLUS, MINUS):
            token = self.current_token
            if token.type == PLUS:
                self.eat(PLUS)
                result += self.term()
            elif token.type == MINUS:
                self.eat(MINUS)
                result -= self.term()
        return result

    def term(self) -> float:
        result = self.factor()
        while self.current_token.type in (TIMES, DIVIDE):
            token = self.current_token
            if token.type == TIMES:
                self.eat(TIMES)
                result *= self.factor()
            elif token.type == DIVIDE:
                self.eat(DIVIDE)
                denominator = self.factor()
                if denominator == 0:
                    raise ZeroDivisionError('division by zero')
                result /= denominator
        return result

    def factor(self) -> float:
        token = self.current_token
        if token.type == PLUS:
            self.eat(PLUS)
            return self.factor()
        if token.type == MINUS:
            self.eat(MINUS)
            return -self.factor()
        if token.type == NUMBER:
            self.eat(NUMBER)
            return float(token.value)
        if token.type == LPAREN:
            self.eat(LPAREN)
            result = self.expr()
            self.eat(RPAREN)
            return result
        self.error(f'Unexpected token: {token}')

def evaluate(expr: str) -> float:
    """
    Evaluate an arithmetic expression containing non‑negative numbers
    (integers or decimals), +, -, *, /, parentheses, spaces and unary minus.
    """
    tokens = tokenize(expr)
    parser = Parser(tokens)
    return parser.parse()
